{"command":"cat << 'EOF' > parse_logic.py
import sys, json, re

def strip_ansi(s):
    return re.sub(r'\x1b\[[0-9;]*m', '', s)

def load_events(f):
    events = []
    for line in f:
        line = line.strip()
        if not line: continue
        events.append(json.loads(line))
    return events

def process_events(events):
    packages = {}
    for ev in events:
        pkg_name = ev.get("Package")
        if not pkg_name: continue
        if pkg_name not in packages:
            packages[pkg_name] = {
                "name": pkg_name,
                "status": "PASS",
                "elapsed": 0.0,
                "cover": "--",
                "tests": {},
                "outputs": [],
                "notest": False
            }

        pkg = packages[pkg_name]
        action = ev.get("Action")
        test_name = ev.get("Test")
        elapsed = ev.get("Elapsed", 0.0)
        output = ev.get("Output", "")

        if not test_name:
            if action in ["pass", "fail", "skip"]:
                pkg["status"] = action.upper()
                pkg["elapsed"] = elapsed
            elif action == "output":
                m = re.search(r"coverage: (\d+\.\d+)% of statements", output)
                if m:
                    pkg["cover"] = m.group(1) + "%"
                if "[no test files]" in output:
                    pkg["notest"] = True
                pkg["outputs"].append(output)
        else:
            if test_name not in pkg["tests"]:
                pkg["tests"][test_name] = {"name": test_name, "status": "PASS", "elapsed": 0.0, "outputs": []}
            t = pkg["tests"][test_name]
            if action in ["pass", "fail", "skip"]:
                t["status"] = action.upper()
                t["elapsed"] = elapsed
            elif action == "output":
                t["outputs"].append(output)

    return packages

if __name__ == '__main__':
    with open('sample_go_test/long.json') as f:
        pkgs = process_events(load_events(f))
        for p in pkgs.values():
            print(p['name'], p['status'], len(p['tests']))
EOF
python3 parse_logic.py"}

