import re

def len_no_ansi(s):
    return len(re.sub(r'\x1b\[[0-9;]*m', '', s))

class Table:
    def __init__(self, headers, format="basic"):
        self.headers = headers
        self.rows = []
        self.format = format

    def add_row(self, row):
        self.rows.append(row)

    def render(self):
        widths = [len_no_ansi(h) for h in self.headers]
        for row in self.rows:
            for i, cell in enumerate(row):
                for line in cell.split('\n'):
                    l = len_no_ansi(line)
                    if l > widths[i]:
                        widths[i] = l

        widths = [w + 2 for w in widths]

        def center(text, width):
            text_len = len_no_ansi(text)
            pad = width - text_len
            left = pad // 2
            right = pad - left
            return (" " * left) + text + (" " * right)

        def left_align(text, width):
            text_len = len_no_ansi(text)
            pad = width - text_len
            return " " + text + (" " * (pad - 1))

        def format_cell(text, width, is_header, col_name):
            if is_header:
                return center(text, width)
            if col_name in ["Package", "Test"]:
                return left_align(text, width)
            return center(text, width)

        lines = []

        if self.format == "basic":
            top = "╭" + "┬".join("─" * w for w in widths) + "╮"
            bot = "╰" + "┴".join("─" * w for w in widths) + "╯"
            mid = "├" + "┼".join("─" * w for w in widths) + "┤"
            lines.append(top)
            h_cells = [format_cell(h, widths[i], True, h) for i, h in enumerate(self.headers)]
            lines.append("│" + "│".join(h_cells) + "│")
            lines.append(mid)
            for row in self.rows:
                split_cells = [c.split('\n') for c in row]
                max_lines = max(len(c) for c in split_cells)
                for line_idx in range(max_lines):
                    row_parts = []
                    for col_idx, cell_lines in enumerate(split_cells):
                        text = cell_lines[line_idx] if line_idx < len(cell_lines) else ""
                        row_parts.append(format_cell(text, widths[col_idx], False, self.headers[col_idx]))
                    lines.append("│" + "│".join(row_parts) + "│")
            lines.append(bot)

        elif self.format == "plain":
            h_cells = [format_cell(h, widths[i], True, h) for i, h in enumerate(self.headers)]
            lines.append(" " + " ".join(h_cells) + " ")
            lines.append(" " + " ".join(" " * w for w in widths) + " ")
            for row in self.rows:
                split_cells = [c.split('\n') for c in row]
                max_lines = max(len(c) for c in split_cells)
                for line_idx in range(max_lines):
                    row_parts = []
                    for col_idx, cell_lines in enumerate(split_cells):
