import sys, json, re, argparse

def strip_ansi(s):
    return re.sub(r'\x1b\[[0-9;]*m', '', s)

def len_no_ansi(s):
    return len(strip_ansi(s))

COLORS = {
    "PASS": "\033[92mPASS\033[0m",
    "FAIL": "\033[91mFAIL\033[0m",
    "SKIP": "\033[93mSKIP\033[0m",
