                status_str, f"{p['elapsed']:.2f}s", pkg_name, p["cover"], str(pass_c), str(fail_c), str(skip_c)
            ])
        has_pkg = True

    if has_pkg:
        print(pkg_tab.render())

    if tests_failed:
        sys.exit(1)

if __name__ == '__main__':
    main()
